class BanditPolicy:
    def __init__(self, K: int, context_dim: int = 0):
        self.K = K
        self.context_dim = context_dim
        self.rng = np.random.default_rng(42)

        if self.context_dim > 0:
            self._lambda = 0.4
            self._v2 = 0.01
            self._B_inv = np.array([np.eye(self.context_dim) / self._lambda for _ in range(self.K)])
            self._f = np.zeros((self.K, self.context_dim), dtype=np.float64)
            self._theta_hat = np.zeros((self.K, self.context_dim), dtype=np.float64)
        else:
            self.reset_mab()

    def reset_mab(self):
        self.era_t = 0
        self.history = [[] for _ in range(self.K)]

    def reset(self):
        if self.context_dim > 0:
            self._B_inv = np.array([np.eye(self.context_dim) / self._lambda for _ in range(self.K)])
            self._f[:] = 0.0
            self._theta_hat[:] = 0.0
        else:
            self.reset_mab()

    def select_arm(self, t: int, context: np.ndarray | None = None) -> int:
        if self.context_dim > 0 and context is not None:
            best_arm = 0
            best_val = -np.inf
            for a in range(self.K):
                mu_a = self._theta_hat[a]
                cov_a = self._v2 * self._B_inv[a]
                eigvals, eigvecs = np.linalg.eigh(cov_a)
                eigvals = np.maximum(eigvals, 0.0)
                z = self.rng.standard_normal(self.context_dim)
                theta_sample = mu_a + eigvecs @ (np.sqrt(eigvals) * z)
                val = np.dot(theta_sample, context)
                if val > best_val:
                    best_val = val
                    best_arm = a
            return int(best_arm)
        else:
            for a in range(self.K):
                if len(self.history[a]) == 0:
                    return a

            best_arm = 0
            best_ucb = -np.inf
            for a in range(self.K):
                n_a = len(self.history[a])
                mu_a = sum(self.history[a]) / n_a
                ucb = kl_ucb_bound(mu_a, n_a, self.era_t, c=1.0)
                if ucb > best_ucb:
                    best_ucb = ucb
                    best_arm = a
            return int(best_arm)

    def update(self, arm: int, reward: float, context: np.ndarray | None = None):
        if self.context_dim > 0 and context is not None:
            x = context
            B = self._B_inv[arm]
            Bx = B @ x
            xBx = np.dot(x, Bx)
            self._B_inv[arm] = B - np.outer(Bx, Bx) / (1.0 + xBx)
            self._f[arm] += reward * x
            self._theta_hat[arm] = self._B_inv[arm] @ self._f[arm]
        else:
            self.history[arm].append(reward)
            self.era_t += 1

            n = len(self.history[arm])
            recent_changes = False
            for W in [20, 50, 100, 200]:
                if n > W + W // 2:
                    n_recent = W
                    n_past = n - W
                    sum_recent = sum(self.history[arm][-W:])
                    sum_past = sum(self.history[arm][:-W])
                    recent_mean = sum_recent / n_recent
                    past_mean = sum_past / n_past
                    all_mean = (sum_recent + sum_past) / n

                    glr = n_past * kl_bernoulli(past_mean, all_mean) + n_recent * kl_bernoulli(recent_mean, all_mean)
                    if glr > 12.0:
                        recent_changes = True
                        break
            if recent_changes:
                self.reset_mab()

